mapper.select:
SELECT
    COUNT(*) AS orderCount,
    IFNULL(SUM(CASE WHEN o.status = 1 THEN 1 ELSE 0 END), 0) AS unpaidOrderCount,
    IFNULL(SUM(CASE WHEN o.status = 6 THEN 1 ELSE 0 END), 0) AS closedOrderCount,
    IFNULL(SUM(CASE WHEN o.status = 1 THEN o.actual_total ELSE 0 END), 0) AS unpaidAmount
FROM tz_order o
WHERE o.shop_id = #{shopId}
  AND o.create_time >= #{startTime}
  AND o.create_time < #{endTime}

SELECT
    COUNT(*) AS paidOrderCount,
    IFNULL(SUM(o.actual_total), 0) AS gmv
FROM tz_order o
WHERE o.shop_id = #{shopId}
  AND o.is_payed = 1
  AND o.pay_time IS NOT NULL
  AND o.pay_time >= #{startTime}
  AND o.pay_time < #{endTime}

SELECT
    COUNT(*) AS refundCount,
    IFNULL(SUM(r.refund_amount), 0) AS refundAmount
FROM tz_order_refund r
WHERE r.shop_id = #{shopId}
  AND r.return_money_sts = 1
  AND r.refund_time IS NOT NULL
  AND r.refund_time >= #{startTime}
  AND r.refund_time < #{endTime}

SELECT
    COUNT(*) AS pendingRefundCount,
    IFNULL(SUM(r.refund_amount), 0) AS pendingRefundAmount
FROM tz_order_refund r
WHERE r.shop_id = #{shopId}
  AND r.return_money_sts = 0
  AND r.apply_time >= #{startTime}
  AND r.apply_time < #{endTime}
